    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    vals = [v for row in grid for v in row]
    bg = max(set(vals), key=vals.count)

    # Extend diagonal sequences of matching non-background cells. Stop at
    # any other colored cell, which acts as an obstacle.
    for color in set(vals) - {bg}:
        for dr, dc in ((1, 1), (1, -1)):
            for r in range(h):
                for c in range(w):
                    if grid[r][c] != color:
                        continue
                    pr, pc = r - dr, c - dc
                    if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                        continue

                    run = []
                    rr, cc = r, c
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                        run.append((rr, cc))
                        rr += dr
                        cc += dc
                    if len(run) < 2:
                        continue

                    for sr, sc, step_r, step_c in (
                        (run[0][0] - dr, run[0][1] - dc, -dr, -dc),
                        (run[-1][0] + dr, run[-1][1] + dc, dr, dc)
                    ):
                        rr, cc = sr, sc
                        while 0 <= rr < h and 0 <= cc < w:
                            if grid[rr][cc] != bg:
                                break
                            out[rr][cc] = color
                            rr += step_r
                            cc += step_c
    return out
